import{_ as p,a0 as d,w as o,s as r,ao as l,I as n,x as a,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"系统管理员喜欢 systemd 的 5 个理由 | LCTT x X-CMD","titleTemplate":false,"description":"系统管理员喜欢 systemd 的 5 个理由 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系统管理员喜欢 systemd 的 5 个理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系统管理员喜欢 systemd 的 5 个理由 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210415 5 reasons sysadmins love systemd","title":"系统管理员喜欢 systemd 的 5 个理由","tag":"202211","desc":""},"relativePath":"202211/20210415 5 reasons sysadmins love systemd.md","filePath":"[post].md"}'),h={name:"202211/20210415 5 reasons sysadmins love systemd.md"};function c(g,s,u,k,m,b){const e=d("Link");return o(),r("div",null,[s[30]||(s[30]=l(`<h1 id="系统管理员喜欢-systemd-的-5-个理由" tabindex="-1">系统管理员喜欢 systemd 的 5 个理由 <a class="header-anchor" href="#系统管理员喜欢-systemd-的-5-个理由" aria-label="Permalink to “系统管理员喜欢 systemd 的 5 个理由”">​</a></h1><blockquote><p>systemd 的速度和易用性使其成为管理现代 Linux 系统的流行方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202211/28/085754t9sztkt26452ys4s.png" alt=""></p><p>系统管理员知道，在一台运行着的<strong>现代计算机</strong>上会发生很多事情：应用程序在后台运行、预定事件等待在特定时间被触发、事件写入日志文件、发送状态报告。在以前，不同的进程可以通过一系列 Unix 工具，来进行有效地管理和监控。然而，现代的计算机运作更为复杂了：本地服务与容器化应用程序一同运行、能够轻松访问云及其运行的集群、实时进程、以及有比以往都多的数据。</p><p>拥有统一的管理方法不但是用户想要的，也是忙碌的系统管理员所迫切渴望的。为了完成这项重要的任务，<ruby>系统守护进程<rt> system daemon </rt></ruby> （<strong>systemd</strong>） 被开发出来，并迅速被所有主要的 Linux 发行版所采用了。</p><p>当然，systemd 并不是管理 Linux 系统的唯一方式，还有许多其他可供选择的初始化系统，包括 sysvinit、OpenRC、runit、s6 和 BusyBox，但 systemd 将 Linux 视为一个统一的数据集，意味着 systemd 能用强大的工具对 Linux 进行一致的操作和查询。对于忙碌的系统管理员和许多用户来说，systemd 的速度和易用性是一个重要的特性。有以下的五个原因。</p><h3 id="启动管理" tabindex="-1">启动管理 <a class="header-anchor" href="#启动管理" aria-label="Permalink to “启动管理”">​</a></h3><p>启动 Linux 计算机可能是一件非常罕见的事情。<strong>服务器</strong>的正常运行时间通常以 <em>年</em> 来计算，而不是月或周。<strong>笔记本电脑和台式机</strong>可能会频繁地关闭和启动，但更多的时候它们是被挂起或休眠了。无论哪种类型，<strong>最近一次开机的时刻</strong>都可用于检查一段时间内的计算机健康情况，因为当你在监视系统或诊断问题时，这一时刻能够限制查看的数据量大小，从而让你快速地找到问题所在。</p><p>如果你不记得上次启动计算机的时间，你可以使用 systemd 的日志记录工具 <code>journalctl</code>，来列出计算机的所有启动会话：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --list-boots</span></span>
<span class="line"><span>-42 7fe7c3... Fri 2020-12-04 05:13:59 - Wed 2020-12-16 16:01:23</span></span>
<span class="line"><span>-41 332e99... Wed 2020-12-16 20:07:39 - Fri 2020-12-18 22:08:13</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>-1 e0fe5f... Mon 2021-03-29 20:47:46 - Mon 2021-03-29 21:59:29</span></span>
<span class="line"><span> 0 37fbe4... Tue 2021-03-30 04:46:13 - Tue 2021-03-30 10:42:08</span></span></code></pre></div><p>最近一次启动会话输出在结果列表的底部，因此你可以通过管道将输出传输到 <code>tail</code>，来查看最近一次启动会话。</p><p>左侧的数字（在本例中为 42、41、1 和 0）是每个启动会话的索引号。换句话说，如果你要查看某一特定启动会话的日志，你可以使用这个索引号作为参数。</p><h3 id="日志检查" tabindex="-1">日志检查 <a class="header-anchor" href="#日志检查" aria-label="Permalink to “日志检查”">​</a></h3><p>查看日志是推断系统信息的一种重要方法。日志提供了计算机运行的大部分事件的历史记录，这些记录都是在没有你直接监督的情况下生成的。通过日志，你可以知道某一服务何时启动、定时任务何时运行、哪些服务在后台运行、哪些事件运行失败等等信息。故障排除的初始步骤是使用 systemd 的 <code>journalctl</code> 来查看日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end</span></span></code></pre></div><p><code>--pager-end</code> 选项（简写为 <code>-e</code>）会从 <code>journalctl</code> 的输出末尾开始查看日志，因此要查看更早发生的日志，你需要向上滚动。</p><p>systemd 维护一个错误信息的“目录”，错误信息包含错误记录、可能的解决方案、支持论坛的链接和开发人员文档。这个错误信息的“目录”能为日志事件提供重要的上下文，否则它可能会成为海量日志中的一个令人困惑的信息，或者更糟的是，错误信息可能会完全被忽视。要将错误消息与日志中的解释性文本放在一起输出，你可以使用 <code>--catalog</code> 选项（简写为 <code>-x</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end --catalog</span></span></code></pre></div><p>要进一步限定日志输出，你可以指定要查看哪个启动会话的日志。因为每个启动会话都有索引，所以你可以使用 <code>--boot</code> 选项，来指定某个启动会话，并仅查看该启动会话的日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end --catalog --boot 42</span></span></code></pre></div><p>你还可以查看特定 systemd 单元的日志。例如，要解决 SSH 服务的问题，你可以指定 <code>--unit sshd</code> 选项，来仅查看适用于 <code>sshd</code> 守护程序的日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end \\</span></span>
<span class="line"><span>    --catalog --boot 42 \\</span></span>
<span class="line"><span>    --unit sshd</span></span></code></pre></div><h3 id="服务管理" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理" aria-label="Permalink to “服务管理”">​</a></h3><p>systemd 的第一个任务就是启动你的计算机，systemd 会迅速、高效且有效地执行这一任务。但 systemd 一直需要管理的任务是服务管理，因为 systemd 需要确保你要运行的服务确实在你的会话期间启动，并继续运行。systemd 的这一功能非常稳健，因为理论上即使是一个崩溃的服务也可以在没有你干预的情况下重新启动。</p><p>你可以通过使用 <code>systemctl</code> 命令来让 systemd 管理服务，并能查看定义服务的 <ruby>单元文件<rt> unit file </rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl cat sshd</span></span>
<span class="line"><span># /usr/lib/systemd/system/sshd.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=OpenSSH server daemon</span></span>
<span class="line"><span>Documentation=man:sshd(8) man:sshd_config(5)</span></span>
<span class="line"><span>After=network.target sshd-keygen.target</span></span>
<span class="line"><span>Wants=sshd-keygen.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=notify</span></span>
<span class="line"><span>EnvironmentFile=-/etc/crypto-policies/back-ends/opensshserver.config</span></span>
<span class="line"><span>EnvironmentFile=-/etc/sysconfig/sshd</span></span>
<span class="line"><span>ExecStart=/usr/sbin/sshd -D $OPTIONS $CRYPTO_POLICY</span></span>
<span class="line"><span>ExecReload=/bin/kill -HUP $MAINPID</span></span>
<span class="line"><span>KillMode=process</span></span>
<span class="line"><span>Restart=on-failure</span></span>
<span class="line"><span>RestartSec=42s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><p>大多数单元文件都在 <code>/usr/lib/systemd/system/</code> 目录下，但是你也可以用局部更改来修改配置，请使用以下的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl edit sshd</span></span></code></pre></div><p>你可以通过 <code>is-active</code> 选项，来查看某一服务当前是否处于活动状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl is-active sshd</span></span>
<span class="line"><span>active</span></span>
<span class="line"><span>$ systemctl is-active foo</span></span>
<span class="line"><span>inactive</span></span></code></pre></div><p>同样地，你可以通过 <code>is-failed</code> 选项，来查看某一服务是否运行失败了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl is-failed sshd</span></span></code></pre></div><p>使用以下命令，来启动或者停止某一服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl stop sshd</span></span>
<span class="line"><span>$ systemctl start sshd</span></span></code></pre></div><p>使用以下命令，让某一服务在开机时自启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl enable sshd</span></span></code></pre></div><p>添加 <code>--now</code> 选项，让某一服务在开机时启动并在当前会话中立即启动。</p><h3 id="定时器管理" tabindex="-1">定时器管理 <a class="header-anchor" href="#定时器管理" aria-label="Permalink to “定时器管理”">​</a></h3>`,38)),n("p",null,[s[1]||(s[1]=a("在以前，当你想在 Linux 上自动执行一项任务时，你可以使用的工具是 ",-1)),s[2]||(s[2]=n("code",null,"cron",-1)),s[3]||(s[3]=a("。如今，",-1)),s[4]||(s[4]=n("code",null,"cron",-1)),s[5]||(s[5]=a(" 命令仍能使用，但对于在 Linux 上自动执行一项任务，也有一些其他好用的替代方案。例如，",-1)),t(e,{href:"https://opensource.com/article/21/2/linux-automation"},{default:i(()=>[...s[0]||(s[0]=[a("anacron 命令",-1)])]),_:1}),s[6]||(s[6]=a(" 是一个多功能的、类似于 ",-1)),s[7]||(s[7]=n("code",null,"cron",-1)),s[8]||(s[8]=a(" 的系统，它能够运行在停机期间可能会错过的任务。",-1))]),n("p",null,[s[10]||(s[10]=a("计划的事件就是在特定时间需要激活的服务。systemd 管理一个名为 ",-1)),t(e,{href:"https://opensource.com/article/20/7/systemd-timers"},{default:i(()=>[...s[9]||(s[9]=[a("定时器",-1)])]),_:1}),s[11]||(s[11]=a(" 的工具，它类似 cron 的功能。你可以使用以下命令，来列出活动中的定时器：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-timers</span></span>
<span class="line"><span>NEXT                          LEFT      </span></span>
<span class="line"><span>Tue 2021-03-30 12:37:54 NZDT  16min left [...]</span></span>
<span class="line"><span>Wed 2021-03-31 00:00:00 NZDT  11h left [...]</span></span>
<span class="line"><span>Wed 2021-03-31 06:42:02 NZDT  18h left [...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3 timers listed.</span></span>
<span class="line"><span>Pass --all to see loaded but inactive timers, too.</span></span></code></pre></div><p>你可以使用以下命令，来像启用服务一样启用定时器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl enable myMonitor.timer</span></span></code></pre></div><h3 id="目标管理" tabindex="-1">目标管理 <a class="header-anchor" href="#目标管理" aria-label="Permalink to “目标管理”">​</a></h3><p><ruby>目标<rt>target</rt></ruby> 是 systemd 的最后一个主要组成部分。像服务和定时器一样，目标也是一个单元文件，也可以以相同的方式启动和启用。目标的独特之处在于它们可以将其他单元文件任意分组。例如，你可能希望开机启动到文本控制台界面而不是图形桌面，因此有一个 <code>multi-user</code> 目标。但是，<code>multi-user</code> 目标只是没有包括桌面单元文件的 <code>graphical</code> 目标。</p><p>简而言之，目标是一种将服务、定时器甚至其他的目标集合在一起，以表示机器的预期状态的简单方法。</p><p>事实上，在 systemd 中，重启、关机或关闭操作只是一个目标而已。</p><p>你可以使用 <code>list-unit-files</code> 选项，用 <code>--type</code> 选项将其限制为 <code>target</code> 来列出所有可用的目标：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type target</span></span></code></pre></div><h3 id="使用-systemd-对计算机进行控制管理" tabindex="-1">使用 systemd 对计算机进行控制管理 <a class="header-anchor" href="#使用-systemd-对计算机进行控制管理" aria-label="Permalink to “使用 systemd 对计算机进行控制管理”">​</a></h3><p>现代的 Linux 使用 systemd 进行服务管理和日志检查。从个人的 Linux 系统到企业服务器，systemd 都能提供有效的监控，并且十分易于维护。你越频繁地使用 systemd，systemd 对你而言就会变得越容易预测和直观，你就会明白系统的不同部分是如何相互关联的。</p>`,11)),n("p",null,[s[13]||(s[13]=a("为了更好地熟悉 systemd，请现在就开始使用它吧。请 ",-1)),t(e,{href:"https://opensource.com/downloads/linux-systemd-cheat-sheet"},{default:i(()=>[...s[12]||(s[12]=[a("下载关于 systemd 相关命令的备忘录",-1)])]),_:1}),s[14]||(s[14]=a("，你可以在实际使用 systemd 中经常参考这个备忘录，这样你就能更快熟悉使用 systemd 啦！",-1))]),s[32]||(s[32]=n("hr",null,null,-1)),n("p",null,[s[16]||(s[16]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/21/4/sysadmins-love-systemd"},{default:i(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/21/4/sysadmins-love-systemd",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[17]||(s[17]=[a("Seth Kenlon",-1)])]),_:1}),s[22]||(s[22]=a(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 译者：",-1)),t(e,{href:"https://github.com/chai001125"},{default:i(()=>[...s[19]||(s[19]=[a("chai001125",-1)])]),_:1}),s[24]||(s[24]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[26]||(s[26]=[a("Linux中国",-1)])]),_:1}),s[29]||(s[29]=a(" 荣誉推出",-1))])])}const v=p(h,[["render",c]]);export{x as __pageData,v as default};
